// Recibe todos los mails no leidos y arma un resumen
const mails = $input.all();

if (mails.length === 0) {
  return [{
    json: {
      hayMails: false,
      resumen: 'Sin mails nuevos no leidos en las ultimas 24 horas.',
      total: 0
    }
  }];
}

// Clasificar mails por prioridad
const urgentes = [];
const importantes = [];
const informativos = [];

// Palabras clave para clasificacion
const keywordsUrgente = ['cliente', 'consulta', 'presupuesto', 'urgente', 'pago', 'factura', 'dm clinical', 'aurea', 'prometheo', 'univerzia'];
const keywordsImportante = ['respuesta', 'seguimiento', 'reunion', 'llamada', 'propuesta'];

for (const mail of mails) {
  const from = mail.json.from || mail.json.From || '';
  const subject = (mail.json.subject || mail.json.Subject || '(sin asunto)').substring(0, 80);
  const snippet = (mail.json.snippet || '').substring(0, 100);
  const date = mail.json.date || mail.json.Date || '';

  const textoCompleto = (subject + ' ' + snippet + ' ' + from).toLowerCase();

  const entrada = `- De: ${from}\n  Asunto: ${subject}\n  Fecha: ${date}`;

  if (keywordsUrgente.some(kw => textoCompleto.includes(kw))) {
    urgentes.push(entrada);
  } else if (keywordsImportante.some(kw => textoCompleto.includes(kw))) {
    importantes.push(entrada);
  } else {
    informativos.push(entrada);
  }
}

// Armar resumen
let resumen = `BRIEFING MATUTINO — ${new Date().toLocaleDateString('es-AR')}\n\n`;

if (urgentes.length > 0) {
  resumen += `URGENTE (${urgentes.length}):\n${urgentes.join('\n\n')}\n\n`;
}
if (importantes.length > 0) {
  resumen += `IMPORTANTE (${importantes.length}):\n${importantes.join('\n\n')}\n\n`;
}
if (informativos.length > 0) {
  resumen += `INFORMATIVO (${informativos.length}):\n${informativos.join('\n\n')}\n\n`;
}

resumen += `---\nTotal: ${mails.length} mails no leidos`;

return [{
  json: {
    hayMails: true,
    resumen: resumen,
    total: mails.length,
    urgentes: urgentes.length,
    importantes: importantes.length,
    informativos: informativos.length
  }
}];
